-- Ledger tables. Do not edit this file after it ships; add a new migration instead.
-- If TypeScript and the database disagree, the database wins.

CREATE TABLE runs (
  id text PRIMARY KEY,
  workflow text NOT NULL,
  mode text NOT NULL,
  started_at timestamptz NOT NULL,
  finished_at timestamptz,
  status text NOT NULL,
  accounts_considered integer NOT NULL DEFAULT 0,
  proposals_created integer NOT NULL DEFAULT 0,
  commits integer NOT NULL DEFAULT 0,
  cost_usd double precision NOT NULL DEFAULT 0,
  error text
);

CREATE TABLE proposals (
  id text PRIMARY KEY,
  kind text NOT NULL,
  target jsonb NOT NULL,
  payload jsonb NOT NULL,
  action_hash text NOT NULL,
  idempotency_key text NOT NULL,
  reasons jsonb NOT NULL,
  procedure text NOT NULL,
  prompt_hash text NOT NULL,
  run_id text NOT NULL,
  policy_decision jsonb NOT NULL,
  state text NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  account_ref jsonb NOT NULL,
  supersedes_id text,
  error text
);

CREATE INDEX proposals_idempotency_key_idx ON proposals (idempotency_key);
CREATE INDEX proposals_run_id_idx ON proposals (run_id);
CREATE INDEX proposals_state_idx ON proposals (state);

CREATE TABLE approvals (
  id text PRIMARY KEY,
  proposal_id text NOT NULL REFERENCES proposals (id),
  approver text NOT NULL,
  decision text NOT NULL,
  action_hash text NOT NULL,
  comment text,
  at timestamptz NOT NULL
);

CREATE INDEX approvals_proposal_idx ON approvals (proposal_id, at DESC);

CREATE TABLE commits (
  id text PRIMARY KEY,
  proposal_id text NOT NULL REFERENCES proposals (id),
  idempotency_key text NOT NULL,
  outcome text NOT NULL,
  hubspot_ids jsonb NOT NULL,
  request jsonb,
  response jsonb,
  at timestamptz NOT NULL
);

CREATE INDEX commits_proposal_idx ON commits (proposal_id, at);

CREATE TABLE audit_log (
  id text PRIMARY KEY,
  at timestamptz NOT NULL,
  actor text NOT NULL,
  action text NOT NULL,
  entity text NOT NULL,
  before jsonb,
  after jsonb
);

CREATE INDEX audit_log_entity_idx ON audit_log (entity, at);

CREATE TABLE idempotency_keys (
  key text PRIMARY KEY,
  proposal_id text NOT NULL,
  created_at timestamptz NOT NULL
);

CREATE TABLE llm_calls (
  id text PRIMARY KEY,
  run_id text NOT NULL,
  procedure text NOT NULL,
  model text NOT NULL,
  tier text NOT NULL,
  input_tokens integer NOT NULL,
  output_tokens integer NOT NULL,
  cost_usd double precision NOT NULL,
  latency_ms integer NOT NULL,
  at timestamptz NOT NULL
);

CREATE INDEX llm_calls_run_idx ON llm_calls (run_id);

CREATE OR REPLACE FUNCTION reject_audit_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'audit_log is append-only';
END;
$$;

CREATE TRIGGER audit_log_append_only
  BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW
  EXECUTE FUNCTION reject_audit_mutation();

CREATE OR REPLACE FUNCTION reject_illegal_proposal_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- If TypeScript and the database disagree, the database wins.
  IF OLD.state IS NOT DISTINCT FROM NEW.state THEN
    RETURN NEW;
  END IF;

  IF NOT (
       (OLD.state = 'proposed' AND NEW.state IN ('auto_approved', 'awaiting_approval', 'escalated', 'rejected'))
    OR (OLD.state = 'auto_approved' AND NEW.state IN ('committed', 'failed', 'superseded'))
    OR (OLD.state = 'awaiting_approval' AND NEW.state IN ('approved', 'rejected', 'superseded', 'expired'))
    OR (OLD.state = 'escalated' AND NEW.state IN ('approved', 'rejected', 'superseded', 'expired'))
    OR (OLD.state = 'approved' AND NEW.state IN ('committed', 'failed', 'superseded'))
    OR (OLD.state = 'failed' AND NEW.state IN ('committed', 'approved'))
  ) THEN
    RAISE EXCEPTION 'Illegal action transition % → %', OLD.state, NEW.state;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER proposals_state_transition
  BEFORE UPDATE ON proposals
  FOR EACH ROW
  EXECUTE FUNCTION reject_illegal_proposal_transition();
